bounded_host_request.command:
set -eu
echo "COMPOSE_LABELS_BEGIN"
docker inspect gace-createvdobot-videobot-poll-1 --format 'PROJECT={{index .Config.Labels "com.docker.compose.project"}} WORKDIR={{index .Config.Labels "com.docker.compose.project.working_dir"}} FILES={{index .Config.Labels "com.docker.compose.project.config_files"}} SERVICE={{index .Config.Labels "com.docker.compose.service"}}'
echo "COMPOSE_LABELS_END"
docker exec deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Atc "SELECT '\''VIDEO_SALE_ROUTE='\''||topic_id||'\'':'\''||chat_id||'\'':'\''||message_thread_id||'\'':'\''||title FROM posting_topics WHERE purpose='\''video_sale'\'' AND enabled=TRUE;"'
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env;
const url='postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim())+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const c=new pg.Client({connectionString:url,connectionTimeoutMillis:5000});
try{await c.connect();
let q=await c.query("SELECT listing_id,revision,status,price_stars,rights_verified,adult_consent_verified,fee_terms_accepted_at IS NOT NULL AS terms,management_fee_bps,thumbnail_file_id IS NOT NULL AS thumbnail,sample_file_id IS NOT NULL AS sample,paid_video_file_id IS NOT NULL AS video FROM videobot_listings WHERE status IN ('draft','ready') ORDER BY updated_at DESC LIMIT 5");
for(const x of q.rows)console.log('LISTING='+JSON.stringify(x));
q=await c.query("SELECT delivery_key,status,paid_message_id FROM videobot_post_receipts ORDER BY updated_at DESC LIMIT 5");
for(const x of q.rows)console.log('RECEIPT='+JSON.stringify(x));
console.log('ENV_THREAD='+Boolean(e.VIDEOBOT_VIDEO_SALE_THREAD_ID));
}finally{await c.end().catch(()=>{})}
NODE
